<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
use FMonitor2\Tests\Support\{LengthQueuedPilotSessionEntropy,NativePilotSessionFilesystem,RecordingPilotSessionObserver,SequencePilotSessionClock};
spl_autoload_register(static function(string$c):void{$p='FMonitor\\IdentityAccess\\';if(str_starts_with($c,$p)){$f=dirname(__DIR__,2).'/app/IdentityAccess/'.substr($c,strlen($p)).'.php';if(is_file($f))require$f;}});assertSameValue(true,class_exists(FMonitor\IdentityAccess\PilotSessionStorageFactory::class),'INTENTIONAL_RED: v7 lock clock owner exists');require dirname(__DIR__).'/Support/PilotSessionStoragePublicApiFixture.php';
$parent=sys_get_temp_dir().'/fmonitor2-session-storage-tests';$root=$parent.'/task-'.bin2hex(random_bytes(8));$dir="$root/sessions/clock_v7";mkdir($dir,0700,true);chmod($root,0700);chmod("$root/sessions",0700);$id=str_repeat('L',16);file_put_contents("$dir/s-$id.session",'clock');chmod("$dir/s-$id.session",0600);$lock="$dir/l-".hash('sha256',$id).'.lock';$held=fopen($lock,'c+b');chmod($lock,0600);flock($held,LOCK_EX);$rm=function(string$p)use(&$rm):void{if(is_file($p)||is_link($p)){unlink($p);return;}if(!is_dir($p))return;foreach(scandir($p)?:[]as$e)if($e!=='.'&&$e!=='..')$rm($p.'/'.$e);rmdir($p);};
try{$make=static fn($fs,$clock)=>(new FMonitor\IdentityAccess\PilotSessionStorageFactory())->create(new FMonitor\IdentityAccess\PilotSessionStorageConfig($root,'clock_v7'),$fs,$clock,new LengthQueuedPilotSessionEntropy([12=>[str_repeat('c',12)]]),new RecordingPilotSessionObserver());$owner=$make(new NativePilotSessionFilesystem(),new SequencePilotSessionClock([1_788_200_000,1_700_000_000,1_900_000_000],[100,1_000_000_100,2_000_000_101]));$started=hrtime(true);$r=$owner->start($id);assertSameValue('LOCK_TIMEOUT',$r->category()?->name,'exact 2-second monotonic deadline');assertSameValue(true,hrtime(true)-$started<1_000_000_000,'deterministic deadline avoids wall wait');assertSameValue('clock',file_get_contents("$dir/s-$id.session"),'forward/backward wall values do not mutate lock-held material');$owner->close();flock($held,LOCK_UN);
 $short=$make(new NativePilotSessionFilesystem('read','committed',1,'short-read'),new SequencePilotSessionClock([1_788_200_000],[1,2,3]));$result=$short->start($id);assertSameValue('READ_FAILED',$result->category()?->name,'short read rejected');assertSameValue('clock',file_get_contents("$dir/s-$id.session"),'short read leaves bytes unchanged');$short->close();echo"PASS: PILOT-SESSION-STORAGE-001 v7 lock/clock/short-read\n";
}finally{@flock($held,LOCK_UN);fclose($held);$rm($root);if(is_dir($parent)&&count(scandir($parent)?:[])===2)rmdir($parent);}
